const input = document.querySelector('#query');
const list = document.querySelector('#results');
const status = document.querySelector('#status');
let timer, controller, version = 0;
input.addEventListener('input', () => {
  const id = ++version;
  clearTimeout(timer);
  controller?.abort();
  list.replaceChildren();
  const q = input.value.trim();
  if (!q) { status.textContent = 'Type a product name'; return; }
  status.textContent = 'Waiting...';
  timer = setTimeout(() => search(q, id), 250);
});
async function search(q, id) {
  controller = new AbortController();
  status.textContent = 'Loading...';
  try {
    const r = await fetch('/api/products?q=' + encodeURIComponent(q),
      {signal:controller.signal});
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const data = await r.json();
    if (id !== version) return;
    for (const product of data) {
      const li = document.createElement('li');
      li.textContent = product.name;
      list.append(li);
    }
    status.textContent = data.length ? `${data.length} products` : 'No results';
  } catch (err) {
    if (id === version && err.name !== 'AbortError')
      status.textContent = 'Unable to load products';
  }
}
